class Solution {
    public int thirdMax(int[] nums) {
        Long first = null, second = null, third = null;
        for (int n : nums) {
            long val = n;
            if ((first != null && val == first) || (second != null && val == second) || (third != null && val == third)) continue;
            if (first == null || val > first) {
                third = second; second = first; first = val;
            } else if (second == null || val > second) {
                third = second; second = val;
            } else if (third == null || val > third) {
                third = val;
            }
        }
        return third == null ? first.intValue() : third.intValue();
    }
}

var thirdMax = function(nums) {
    let first = null, second = null, third = null;
    for (const n of nums) {
        if (n === first || n === second || n === third) continue;
        if (first === null || n > first) {
            third = second; second = first; first = n;
        } else if (second === null || n > second) {
            third = second; second = n;
        } else if (third === null || n > third) {
            third = n;
        }
    }
    return third !== null ? third : first;
